import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner keyboard = new Scanner(System.in);
        System.out.println("Enter a number: ");
        int firstNum = keyboard.nextInt();
        System.out.println("Enter another number: ");
        int secondNum = keyboard.nextInt();
        System.out.println("Choose an operation:\n1. add\n2. substract\n3. multiply\n4. divide\n5. exponentiation");
        int operation = keyboard.nextInt();
        if (operation == 1) {
            System.out.println("%d + %d = %d".formatted(firstNum, secondNum, firstNum + secondNum));
        } else if (operation == 2) {
            System.out.println("%d - %d = %d".formatted(firstNum, secondNum, firstNum - secondNum));
        } else if (operation == 3) {
            System.out.println("%d * %d = %d".formatted(firstNum, secondNum, firstNum * secondNum));
        } else if (operation == 4) {
            System.out.println("%d / %d = %d".formatted(firstNum, secondNum, firstNum / secondNum));
        } else if (operation == 5) {
            System.out.println("%d^%d = %f".formatted(firstNum, secondNum, Math.pow(firstNum, secondNum)));
        }
        keyboard.close();
    }
}

