import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        final int MINIMUM = 32;
        final int MAXIMUM = 127;
        Scanner keyboard = new Scanner(System.in);
        System.out.print("Enter a number from 32 to 127: ");
        int value = keyboard.nextInt();
        if (value < MINIMUM || value > MAXIMUM) {
            System.out.println("Invalid number.");
            keyboard.close();
            return;
        }
        System.out.println("Your value is " + (char) value);
        for (int code = MINIMUM; code <= 255; code++) {
            System.out.printf("%s ( %3d)  ", String.valueOf((char) code), code);
            if ((code - MINIMUM + 1) % 6 == 0) System.out.println();
        }
        keyboard.close();
    }
}

