            System.out.println(" ".repeat(number / 2 - i) + "*".repeat(i * 2 + 1));
        }
        for (int i = 0; i < TRUNK_HEIGHT; i++) {
            System.out.println(" ".repeat(number / 2 - 1) + "*".repeat(TRUNK_WIDTH));
        }
