import java.util.HashMap;
import java.util.Scanner;

public class Main {
    static Scanner keyboard = new Scanner(System.in);

    public static void main(String[] args) {
        System.out.print("Choose age, scrabble or months: ");
        String exercise = keyboard.nextLine().trim().toLowerCase();
        switch (exercise) {
            case "age" -> age();
            case "scrabble" -> scrabble();
            case "months" -> daysInMonth();
            default -> System.out.println("Unknown exercise.");
        }
        keyboard.close();
    }

    public static void daysInMonth() {
        System.out.print("Enter a month number (1 = January): ");
        int monthNum = readInt();
        System.out.print("Enter a year (4 digits): ");
        int yearNum = readInt();
        if (monthNum < 1 || monthNum > 12) {
            printRes("Invalid month");
            return;
        }
        String[] month = getMonths(yearNum)[monthNum - 1];
        printRes("In %d %s has %s days.".formatted(yearNum, month[0], month[1]));
    }

    public static String[][] getMonths(int yearNum) {
        boolean leap = yearNum % 400 == 0 || (yearNum % 4 == 0 && yearNum % 100 != 0);
        return new String[][] {
            {"January", "31"}, {"February", leap ? "29" : "28"}, {"March", "31"},
            {"April", "30"}, {"May", "31"}, {"June", "30"}, {"July", "31"},
            {"August", "31"}, {"September", "30"}, {"October", "31"},
            {"November", "30"}, {"December", "31"}
        };
    }

    public static void printRes(Object value) { System.out.println(value); }
    public static int readInt() { return keyboard.nextInt(); }
    public static char readChar() { return keyboard.next().toLowerCase().charAt(0); }

    public static void scrabble() {
        System.out.print("What letter do you want to check? ");
        printRes(scrabbleScore(readChar()));
    }

    public static void age() {
        System.out.print("What is your age? ");
        printRes(ageCat(readInt()));
    }

    public static String ageCat(int age) {
        if (age < 2) return "Baby";
        if (age < 12) return "Child";
        if (age < 17) return "Teenager";
        return "Adult";
    }

    public static String scrabbleScore(char letter) {
        HashMap<Character, Integer> scores = new HashMap<>();
        String[][] groups = {{"aeilnorst u", "1"}, {"dg", "2"}, {"bcmp", "3"},
                {"fhvwy", "4"}, {"k", "5"}, {"jx", "8"}, {"qz", "10"}};
        for (String[] group : groups)
            for (char c : group[0].replace(" ", "").toCharArray())
                scores.put(c, Integer.parseInt(group[1]));
        if (scores.containsKey(letter)) return "This letter counts for %d points".formatted(scores.get(letter));
        return "Not a valid letter";
    }
}

