import java.util.Locale;
class Box {
    private String type;
    private double length;
    private double width;
    private double height;
    public Box(String type, double length, double width, double height) {
        this.type = type;
        this.length = length;
        this.width = width;
        this.height = height;
    }
    public Box(String type, double length) {
        this.type = type;
        this.length = length;
        this.width = length;
        this.height = length;
    }

    public double surface() {
        return this.width * this.length * 2 + this.width * this.height * 2 + this.height * this.length * 2;
    }

    public double volume() {
        return this.width * this.length * this.height;
    }

    public double tapeLength() {
        double small = Math.min(this.length, this.height);
        double smaller = Math.min(Math.max(this.length, this.height), this.width);
        return small * 2 + smaller * 2;
    }

    public String toString() {
        return String.format(Locale.GERMANY, "Type: %s%nLength: %.1fcm%nWidth: %.1fcm%nHeight: %.1fcm%nSurface: %.1fcm²%nVolume: %.1fcm³%nMinimum tapelength: %.1fcm%n",
                this.type, this.length, this.width, this.height, surface(), volume(), tapeLength());
    }
}
