class PerfectNumber {
    public String getPerfect(int number) {
        int sum = 0;
        StringBuilder perfect = new StringBuilder();
        for (int i = 1; i < number; i++) {
            if (number % i == 0) {
                sum += i;
                perfect.append(i);
                perfect.append(" ");
            }
        }
        if (sum == number) {
            return perfect.toString();
        } else {
            return null;
        }
    }
}
class TestPerfectNumber {
