        PerfectNumber perfect = new PerfectNumber();

        for (int number = 2; number <= 10000; number++) {
            String divisors = perfect.getPerfect(number);
            if (divisors != null) {
                System.out.println(number + " --> " + divisors);
            }
        }
    }
}

